// Фикстура экранного искажения (§46 Спецификации).
//
// Кадр намеренно «геометрический»: сетка контрастных квадратов и цветные
// маркеры по краям. По нему видно, сдвинулась ли картинка (волна, шум) и
// разошлись ли каналы (channel shift), а однотонный фон такое движение скрыл бы.
//
// Сцена ничего не делает каждый кадр: эффект применяется к уже нарисованному
// кадру пост-проходом, поэтому «источник» — сама сцена, а вспомогательная
// текстура — процедурный шум движка.

$.ready(($) => {
    $.world.gravity(0, 0).color('#101820');

    // Сетка: чередование светлых и тёмных клеток с чёткой границей.
    for (let y = 0; y < 12; y++) {
        for (let x = 0; x < 20; x++) {
            $('<rect>', { class: 'cell' })
                .at(32 + x * 64, 32 + y * 32)
                .size(64, 32)
                .color((x + y) % 2 ? '#e8f0ff' : '#1b2740')
                .appendTo($.world);
        }
    }
    // Маркеры каналов: чистый красный, зелёный, синий слева и справа —
    // по ним проверяется сдвиг R/B относительно G.
    $('<rect>', { id: 'marker-r' }).at(40, 420).size(120, 120).color('#ff0000').appendTo($.world);
    $('<rect>', { id: 'marker-g' }).at(40, 560).size(120, 120).color('#00ff00').appendTo($.world);
    $('<rect>', { id: 'marker-b' }).at(180, 420).size(120, 120).color('#0000ff').appendTo($.world);
    $('<rect>', { id: 'marker-w' }).at(180, 560).size(120, 120).color('#ffffff').appendTo($.world);
});
